import Image from "next/image";
import { cn } from "@/lib/utils";

/**
 * Original flat illustrations, generated by scripts/illustrations/build.mjs into
 * public/images/illustrations (one shared palette, figure and object set).
 * Scenes are 400x300, spots (services, shipping guide) 240x180. The fixed aspect
 * ratio reserves space, so nothing shifts while they load.
 */
const SCENE = { width: 400, height: 300 } as const;
const SPOT = { width: 240, height: 180 } as const;

export const ILLUSTRATIONS = {
  requestQuote: { file: "request-quote", ...SCENE },
  teamReview: { file: "team-review", ...SCENE },
  quoteReceived: { file: "quote-received", ...SCENE },
  handover: { file: "handover", ...SCENE },
  containerLoading: { file: "container-loading", ...SCENE },
  tracking: { file: "tracking", ...SCENE },
  receiveParcel: { file: "receive-parcel", ...SCENE },
  supportChat: { file: "support-chat", ...SCENE },
  packParcel: { file: "pack-parcel", ...SCENE },
  routeMap: { file: "route-map", ...SCENE },
  connections: { file: "connections", ...SCENE },
  serviceParcels: { file: "service-parcels", ...SPOT },
  serviceBarrels: { file: "service-barrels", ...SPOT },
  serviceAir: { file: "service-air", ...SPOT },
  serviceSea: { file: "service-sea", ...SPOT },
  serviceVehicle: { file: "service-vehicle", ...SPOT },
  serviceCommercial: { file: "service-commercial", ...SPOT },
  guidePacking: { file: "guide-packing", ...SPOT },
  guideLabelling: { file: "guide-labelling", ...SPOT },
  guideList: { file: "guide-list", ...SPOT },
} as const;

export type IllustrationName = keyof typeof ILLUSTRATIONS;

/** `alt` comes from the "illustrations" namespace (same key as `name`). */
export function Illustration({ name, alt, className, priority }: { name: IllustrationName; alt: string; className?: string; priority?: boolean }) {
  const { file, width, height } = ILLUSTRATIONS[name];
  return (
    <Image
      src={`/images/illustrations/${file}.svg`}
      alt={alt}
      width={width}
      height={height}
      // Vector files: served as-is, no raster optimisation needed.
      unoptimized
      priority={priority}
      className={cn("h-auto w-full select-none", className)}
      draggable={false}
    />
  );
}
